package brozzerlogger;

import com.google.common.base.Strings;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.Collections;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Maintains the set of item IDs that count as bingo drops, sourced from a remote
 * published-Google-Sheet CSV ({@code bingoListUrl}) and polled periodically.
 *
 * <p>Threading: {@link #itemIds} is {@code volatile} because it is written from the
 * okhttp / executor threads and read from the client thread (in {@code onLootReceived}
 * via {@link #getItemIds()}). The executor is RuneLite's shared pool, so {@link #stop()}
 * only cancels our task - it never shuts the pool down.
 */
@Slf4j
@Singleton
public class BingoItemList
{
    private static final long REFRESH_MINUTES = 15;

    private final BrozzerLoggerConfig config;
    private final OkHttpClient okHttpClient;
    private final ScheduledExecutorService executor;

    // Item IDs matched against loot, fetched from the remote list.
    private volatile Set<Integer> itemIds = Collections.emptySet();

    // Periodic poll of the remote list. Cancelled in stop().
    private ScheduledFuture<?> refreshFuture;

    @Inject
    BingoItemList(BrozzerLoggerConfig config, OkHttpClient okHttpClient, ScheduledExecutorService executor)
    {
        this.config = config;
        this.okHttpClient = okHttpClient;
        this.executor = executor;
    }

    void start()
    {
        scheduleRemoteRefresh();
    }

    void stop()
    {
        cancelRefresh();
        itemIds = Collections.emptySet();
    }

    /** The effective match set. Safe to read from the client thread. */
    Set<Integer> getItemIds()
    {
        return itemIds;
    }

    // ---------- Remote bingo list (published Google Sheet CSV) ----------

    void scheduleRemoteRefresh()
    {
        cancelRefresh();
        if (Strings.isNullOrEmpty(config.bingoListUrl()))
        {
            // No URL configured: drop any previously-fetched IDs.
            itemIds = Collections.emptySet();
            return;
        }
        // Fire immediately (initialDelay 0) then poll. Runs on the executor thread;
        // the fetch itself is an async okhttp call, so nothing blocks.
        refreshFuture = executor.scheduleWithFixedDelay(
            this::fetchRemoteList, 0, REFRESH_MINUTES, TimeUnit.MINUTES);
    }

    private void cancelRefresh()
    {
        if (refreshFuture != null)
        {
            refreshFuture.cancel(false);
            refreshFuture = null;
        }
    }

    private void fetchRemoteList()
    {
        String url = config.bingoListUrl();
        if (Strings.isNullOrEmpty(url))
        {
            return;
        }
        HttpUrl parsed = HttpUrl.parse(url);
        if (parsed == null)
        {
            log.debug("Malformed bingo list URL: {}", url);
            return;
        }

        Request request = new Request.Builder().url(parsed).build();
        okHttpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.debug("Failed to fetch bingo list", e);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response r = response)
                {
                    if (!r.isSuccessful() || r.body() == null)
                    {
                        log.debug("Bingo list fetch returned HTTP {}", r.code());
                        return;
                    }
                    Set<Integer> ids = Utils.parseCsv(r.body().string());
                    itemIds = ids.isEmpty()
                            ? Collections.emptySet()
                            : Collections.unmodifiableSet(ids);
                    log.debug("Loaded {} bingo item IDs", itemIds.size());
                }
                catch (IOException e)
                {
                    log.debug("Error reading bingo list response", e);
                }
            }
        });
    }
}

package brozzerlogger;

import lombok.Getter;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BrozzerLoggerConfig.GROUP)
public interface BrozzerLoggerConfig extends Config
{
    String GROUP = "brozzerLogger";

    @Getter
    public enum TeamColor
    {
        RED(0xE6194B),
        ORANGE(0xF58231),
        YELLOW(0xFFE119),
        GREEN(0x3CB44B),
        BLUE(0x4363D8),
        PURPLE(0x911EB4),
        GRAY(0x808080);

        private final int rgb;

        TeamColor(int rgb) { this.rgb = rgb; }

    }

    @ConfigSection(
        name = "Discord/Bingo URLs",
        description = "URLs for discord webhook and bingo item id list",
        position = 0
    )
    String urls = "urls";

    @ConfigItem(
        keyName = "discordWebhookUrl",
        name = "Discord Webhook URL",
        description = "Enter the discord webhook URL to send content to.",
        section = urls
    )
    String webhook();

    @ConfigItem(
        keyName = "bingoListUrl",
        name = "Bingo List URL",
        description = "Link to a published Google Sheet (CSV) listing the bingo item IDs. "
            + "Everyone who uses the same link shares one centrally-managed list. "
            + "Leave blank to disable.",
        section = urls
    )
    default String bingoListUrl()
    {
        return "";
    }

    @ConfigItem(
        keyName = "name",
        name = "Team Name",
        description = "Team name for your team's Discord embeds. Defaults to 'Bingo Loot' if blank.",
        position = 1
    )
    default String teamName()
    {
        return "Bingo Loot";
    }

    @ConfigItem(
        keyName = "color",
        name = "Team Color",
        description = "Color used for your team's Discord embeds. Defaults to gray if unset.",
        position = 2
    )
    default TeamColor teamColor()
    {
        return TeamColor.GRAY;
    }

    @ConfigItem(
        keyName = "sendScreenshot",
        name = "Send Screenshot",
        description = "Attach a screenshot once bingo drop is detected",
        position = 3
    )
    default boolean sendScreenshot()
    {
        return true;
    }
}

package brozzerlogger;

import java.time.Instant;
import com.google.inject.Provides;

import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.apache.commons.lang3.StringUtils;

import java.util.Set;

@Slf4j
@PluginDescriptor(
        name = "Brozzer Logger",
        description = "Sends bingo-relevant drops to a Discord webhook using Google Sheets for bingo list",
        tags = {"bingo", "clan", "loot", "webhook", "discord"},
        configName = "BingoDiscordLoggerPlugin"
)
public class BrozzerLoggerPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private BrozzerLoggerConfig config;

    @Inject
    private ItemManager itemManager;

    @Inject
    private BingoItemList bingoItemList;

    @Inject
    private DiscordWebhookClient webhookClient;

    @Override
    protected void startUp() throws Exception
    {
        log.debug("BingoDiscordLogger started!");
        bingoItemList.start();
    }

    @Override
    protected void shutDown() throws Exception
    {
        log.debug("BingoDiscordLogger stopped!");
        bingoItemList.stop();
    }

    @Provides
    BrozzerLoggerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(BrozzerLoggerConfig.class);
    }

    private String getPlayerName()
    {
        return client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : "Unknown";
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!BrozzerLoggerConfig.GROUP.equals(event.getGroup()))
        {
            return;
        }
        if ("bingoListUrl".equals(event.getKey()))
        {
            // URL changed: reschedule (an empty URL stops polling) and refetch now.
            bingoItemList.scheduleRemoteRefresh();
        }
    }

    @Subscribe
    public void onLootReceived(LootReceived lootReceived)
    {
        // If item obtained via Player Kill, exit
        LootRecordType type = lootReceived.getType();
        if (type == LootRecordType.PLAYER)
        {
            return;
        }

        // No bingo items configured - nothing to match against
        Set<Integer> currentIds = bingoItemList.getItemIds();
        if (currentIds.isEmpty())
        {
            return;
        }

        // Send valid bingo loot to webhook
        processLoot(lootReceived, currentIds);
    }


    /**
     * Formats loot data into an embedding then sends it via webhook to Discord.
     *
     * @param lootReceived      The loot data that will be processed
     * @param currentIds        The list of bingo-relevant item IDs
     */
    private void processLoot(LootReceived lootReceived, Set<Integer> currentIds)
    {
        // Build the structured payload for the bot
        WebhookBody.Payload payload = new WebhookBody.Payload();
        payload.setPlayer(getPlayerName());
        payload.setSource(lootReceived.getName());
        payload.setSourceType(lootReceived.getType().name());
        payload.setCombatLevel(lootReceived.getCombatLevel());
        payload.setTimestamp(System.currentTimeMillis());

        // Build a description listing each matched bingo item
        StringBuilder dropList = new StringBuilder();
        for (ItemStack stack : lootReceived.getItems())
        {
            int canonicalId = itemManager.canonicalize(stack.getId());
            if (!currentIds.contains(canonicalId))
            {
                continue;
            }

            ItemComposition comp = itemManager.getItemComposition(canonicalId);

            WebhookBody.Payload.Item item = new WebhookBody.Payload.Item();
            item.setId(canonicalId);
            item.setName(comp.getName());
            item.setQuantity(stack.getQuantity());
            payload.getItems().add(item);

            if (dropList.length() > 0)
            {
                dropList.append("\n");
            }
            // Bold the item name so it stands out in the embed body
            dropList.append(stack.getQuantity()).append(" x ")
                    .append(comp.getName());
        }

        if (payload.getItems().isEmpty())
        {
            log.debug("step payload getItems is empty");
            return;
        }

        // Create Discord embedding
        WebhookBody.Embed embed = new WebhookBody.Embed();

        int color = config.teamColor().getRgb();
        embed.setColor(color); // User-selected color is used. Defaults to gray

        String title = StringUtils.isBlank(config.teamName())
                ? "Bingo Loot"
                : config.teamName() + " — Bingo Loot";
        embed.setTitle(title); // User-defined team name is used. Defaults to Bingo Loot

        String description = payload.getPlayer() + " has looted:\n\n" + dropList + "\nFrom: " + payload.getSource();
        embed.setDescription(description);

        WebhookBody.Author author = new WebhookBody.Author();
        author.setName(payload.getPlayer());
        embed.setAuthor(author);

        if (config.sendScreenshot())
        {
            WebhookBody.Image image = new WebhookBody.Image();
            image.setUrl("attachment://image.png");
            embed.setImage(image);
        }

        // ISO 8601 in UTC. Discord renders this in each viewer's local timezone.
        // Example: "2026-05-28T19:43:27.000Z" -> "Today at 3:43 PM" for EST viewers.
        embed.setTimestamp(Instant.ofEpochMilli(payload.getTimestamp()).toString());

        WebhookBody body = new WebhookBody();
        body.getEmbeds().add(embed);
        body.setBingo(payload);

        webhookClient.send(body);
    }
}

package brozzerlogger;

import com.google.common.base.Strings;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;
import okhttp3.*;

import static net.runelite.http.api.RuneLiteAPI.GSON;

/**
 * Sends a {@link WebhookBody} to one or more Discord webhooks as multipart/form-data.
 *
 * <p>When screenshots are enabled the next rendered frame is grabbed via
 * {@link DrawManager} and attached as the {@code file} part named {@code image.png},
 * which the embed references via {@code attachment://image.png}. The configured
 * webhook string may contain several newline-separated URLs; each is validated and
 * sent independently.
 */
@Slf4j
@Singleton
public class DiscordWebhookClient
{
    private final BrozzerLoggerConfig config;
    private final OkHttpClient okHttpClient;
    private final DrawManager drawManager;

    @Inject
    DiscordWebhookClient(BrozzerLoggerConfig config, OkHttpClient okHttpClient, DrawManager drawManager)
    {
        this.config = config;
        this.okHttpClient = okHttpClient;
        this.drawManager = drawManager;
    }

    void send(WebhookBody body)
    {
        String configUrls = config.webhook();
        if (Strings.isNullOrEmpty(configUrls))
        {
            log.debug("Webhook URL not configured, skipping send");
            return;
        }

        if (config.sendScreenshot())
        {
            drawManager.requestNextFrameListener(image ->
            {
                BufferedImage bufferedImage = (BufferedImage) image;
                byte[] imageBytes = null;
                try
                {
                    imageBytes = convertImageToByteArray(bufferedImage);
                }
                catch (IOException e)
                {
                    log.error("Error converting image to byte array", e);
                }
                send(body, imageBytes);
                log.debug("Body of WebhookBody is \n{}", body);
            });
        }
        else
        {
            send(body, null);
        }
    }

    private void send(WebhookBody body, byte[] screenshot)
    {
        String configUrl = config.webhook();
        HttpUrl url = HttpUrl.parse(configUrl);
        if (url == null)
        {
            log.debug("Malformed webhook URL: {}", configUrl);
            return;
        }
        MultipartBody.Builder requestBodyBuilder = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("payload_json", GSON.toJson(body));
        if (screenshot != null)
        {
            requestBodyBuilder.addFormDataPart("file", "image.png",
                RequestBody.create(MediaType.parse("image/png"), screenshot));
        }


        Request request = new Request.Builder()
            .url(url)
            .post(requestBodyBuilder.build())
            .build();

        okHttpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                log.debug("Error submitting webhook: ", e);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (ResponseBody responseBody = response.body())
                {
                    if (!response.isSuccessful())
                    {
                        String bodyText = responseBody != null ? responseBody.string() : "<no body>";
                        log.debug("Webhook returned {}: {}", response.code(), bodyText);
                    }
                }
                catch (IOException e)
                {
                    log.debug("Failed to read webhook response body: ", e);
                }
                response.close();
            }
        });
    }

    private static byte[] convertImageToByteArray(BufferedImage bufferedImage) throws IOException
    {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        ImageIO.write(bufferedImage, "png", out);
        return out.toByteArray();
    }
}

package brozzerlogger;

import com.google.common.base.Splitter;
import java.util.HashSet;
import java.util.Set;

/**
 * Shared, stateless helpers for the bingo plugin. Kept separate from the classes that
 * own threading/IO so the pure logic here can be exercised directly in unit tests.
 */
final class Utils
{
	private Utils()
	{
	}

	/**
	 * Parse a published-Google-Sheet CSV listing the bingo item IDs. Each row's first
	 * column is the item ID; any row whose first column isn't an integer (header, blank,
	 * comment) is skipped.
	 */
	static Set<Integer> parseCsv(String csv)
	{
		Set<Integer> ids = new HashSet<>();
		for (String line : Splitter.on('\n').omitEmptyStrings().trimResults().split(csv))
		{
			int comma = line.indexOf(',');
			String first = (comma >= 0 ? line.substring(0, comma) : line).trim();
			try
			{
				ids.add(Integer.parseInt(first));
			}
			catch (NumberFormatException e)
			{
				// header / comment / blank row - ignore
			}
		}
		return ids;
	}
}

package brozzerlogger;

import com.google.gson.annotations.SerializedName;
import java.util.ArrayList;
import java.util.List;
import lombok.Data;

@Data
class WebhookBody
{
    private String content;

    private List<Embed> embeds = new ArrayList<>();

    // Our structured bot payload. Discord ignores unknown top-level fields,
    // so this rides along untouched in payload_json.
    private Payload bingo;

    @Data
    static class Embed
    {
        private int color;
        private String title;
        private String description;
        private Author author;
        private List<Field> fields = new ArrayList<>();
        private Image image;
        private String timestamp;
    }

    @Data
    static class Author
    {
        private String name;
        // Optional - small avatar to the left of the name.
        @SerializedName("icon_url")
        private String iconUrl;
    }

    @Data
    static class Field
    {
        private String name;
        private String value;
        // Inline fields render side-by-side in columns rather than stacked.
        private boolean inline;
    }

    @Data
    static class Image
    {
        // Either a real URL or "attachment://filename.png" to reference an
        // uploaded file from the same multipart POST.
        private String url;
    }

    @Data
    static class Payload
    {
        private String player;
        private String source;
        private String sourceType;
        private int combatLevel;
        private long timestamp;
        private List<Item> items = new ArrayList<>();

        @Data
        static class Item
        {
            private int id;
            private String name;
            private int quantity;
        }
    }
}

package brozzerlogger;

import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Player;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Captor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.lenient;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

/**
 * Behavioural tests for the core matching logic in
 * {@link BrozzerLoggerPlugin#onLootReceived(LootReceived)}:
 * PvP loot is dropped, an empty bingo set is a no-op, only items whose
 * {@code canonicalize}d ID is in the set are forwarded, and the captured
 * {@link WebhookBody} carries the right structured data.
 */
@RunWith(MockitoJUnitRunner.Silent.class)
public class BingoLootMatchingTest
{
	@Mock
	private Client client;

	@Mock
	private BrozzerLoggerConfig config;

	@Mock
	private ItemManager itemManager;

	@Mock
	private BingoItemList bingoItemList;

	@Mock
	private DiscordWebhookClient webhookClient;

	@Mock
	private Player localPlayer;

	@Captor
	private ArgumentCaptor<WebhookBody> bodyCaptor;

	@InjectMocks
	private BrozzerLoggerPlugin plugin;

	@Before
	public void setUp()
	{
		lenient().when(client.getLocalPlayer()).thenReturn(localPlayer);
		lenient().when(localPlayer.getName()).thenReturn("Zezima");
		// By default, item IDs are already canonical (identity); overridden where noted.
		lenient().when(itemManager.canonicalize(anyInt())).thenAnswer(inv -> inv.getArgument(0));
		lenient().when(config.sendScreenshot()).thenReturn(false);
		lenient().when(config.teamColor()).thenReturn(BrozzerLoggerConfig.TeamColor.GRAY);
	}

	private static LootReceived loot(LootRecordType type, ItemStack... items)
	{
		Collection<ItemStack> stacks = Arrays.asList(items);
		return new LootReceived("Abyssal demon", 124, type, stacks, items.length, "meta");
	}

	private void stubBingoSet(Integer... ids)
	{
		Set<Integer> set = ids.length == 0
				? Collections.emptySet()
				: new HashSet<>(Arrays.asList(ids));
		when(bingoItemList.getItemIds()).thenReturn(set);
	}

	private void stubItemName(int id, String name)
	{
		ItemComposition comp = org.mockito.Mockito.mock(ItemComposition.class);
		lenient().when(comp.getName()).thenReturn(name);
		when(itemManager.getItemComposition(id)).thenReturn(comp);
	}

	@Test
	public void playerKillLootIsIgnored()
	{
		plugin.onLootReceived(loot(LootRecordType.PLAYER, new ItemStack(4151, 1)));

		verifyNoInteractions(webhookClient);
	}

	@Test
	public void emptyBingoSetIsANoOp()
	{
		stubBingoSet(); // empty

		plugin.onLootReceived(loot(LootRecordType.NPC, new ItemStack(4151, 1)));

		verifyNoInteractions(webhookClient);
	}

	@Test
	public void noMatchingItemsDoesNotSend()
	{
		stubBingoSet(4151);

		// Only a non-bingo item dropped.
		plugin.onLootReceived(loot(LootRecordType.NPC, new ItemStack(995, 100)));

		verifyNoInteractions(webhookClient);
	}

	@Test
	public void matchingItemBuildsAndSendsPayload()
	{
		stubBingoSet(4151);
		stubItemName(4151, "Abyssal whip");

		// Whip matches; coins do not.
		plugin.onLootReceived(loot(LootRecordType.NPC,
				new ItemStack(4151, 2), new ItemStack(995, 100)));

		verify(webhookClient).send(bodyCaptor.capture());
		WebhookBody body = bodyCaptor.getValue();

		WebhookBody.Payload bingo = body.getBingo();
		assertEquals("Zezima", bingo.getPlayer());
		assertEquals("Abyssal demon", bingo.getSource());
		assertEquals("NPC", bingo.getSourceType());
		assertEquals(124, bingo.getCombatLevel());

		assertEquals("only the matching item is included", 1, bingo.getItems().size());
		WebhookBody.Payload.Item item = bingo.getItems().get(0);
		assertEquals(4151, item.getId());
		assertEquals("Abyssal whip", item.getName());
		assertEquals(2, item.getQuantity());

		assertEquals(1, body.getEmbeds().size());
		WebhookBody.Embed embed = body.getEmbeds().get(0);
		assertEquals("Bingo Loot", embed.getTitle());
		assertTrue(embed.getDescription().contains("2 x Abyssal whip"));
		assertEquals("Zezima", embed.getAuthor().getName());
		// Screenshot disabled -> no attachment image referenced.
		assertNull(embed.getImage());
	}

	@Test
	public void notedVariantIsCanonicalizedBeforeMatching()
	{
		stubBingoSet(4151);
		stubItemName(4151, "Abyssal whip");
		// 4152 is the noted form; canonicalize resolves it to the un-noted 4151.
		when(itemManager.canonicalize(4152)).thenReturn(4151);

		plugin.onLootReceived(loot(LootRecordType.NPC, new ItemStack(4152, 1)));

		verify(webhookClient).send(bodyCaptor.capture());
		WebhookBody.Payload.Item item = bodyCaptor.getValue().getBingo().getItems().get(0);
		assertEquals(4151, item.getId());
		assertEquals("Abyssal whip", item.getName());
	}

	@Test
	public void screenshotEnabledReferencesAttachmentImage()
	{
		when(config.sendScreenshot()).thenReturn(true);
		stubBingoSet(4151);
		stubItemName(4151, "Abyssal whip");

		plugin.onLootReceived(loot(LootRecordType.NPC, new ItemStack(4151, 1)));

		verify(webhookClient).send(bodyCaptor.capture());
		WebhookBody.Image image = bodyCaptor.getValue().getEmbeds().get(0).getImage();
		assertEquals("attachment://image.png", image.getUrl());
	}
}

